#include <map>
#include <functional>

int main() {
    // c1 uses default std::less
    std::map<float, std::string> c1;
    c1[1.0f] = "A";

    // c2 uses explicit std::less
    std::map<float, std::string, std::less<float>> c2;
    c2[1.0f] = "A";

    // OK: Same type (Key, Value, Comparator)
    bool eq = (c1 == c2);

    // DANGER: Different comparator type (Compile Error)
    // std::map<float, std::string, std::greater<float>> c3;
    // bool fail = (c1 == c3); 

    return 0;
}
